// Folio stickers (2026-11-26): 3 packs x 6, webp base64.
const F={"bf-cheers": "", "bf-clubkey": "", "bf-gmfren": "", "bf-levelup": "", "bf-streak": "", "bf-thx": "", "cm-captured": "", "cm-gmworld": "", "cm-iwasthere": "", "cm-neverforget": "", "cm-record": "", "cm-witness": "", "gm-alpha": "", "gm-gm": "", "gm-gmfc": "", "gm-gn": "", "gm-live": "", "gm-wowow": ""};
export function stickerResponse(name){const b=F[name];if(!b)return null;const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return new Response(u,{headers:{"content-type":"image/webp","cache-control":"public, max-age=86400","access-control-allow-origin":"*"}})}
